mapper.select:
SELECT COUNT(1) FROM sku s INNER JOIN sc_sku_activity r ON r.goods_id = s.goods_id AND r.source = s.source AND r.channel = s.channel AND r.status = 1 INNER JOIN group_buy_activity a ON a.activity_id = r.activity_id AND a.status = 1 AND a.start_time <= NOW() AND a.end_time > NOW() WHERE s.status = 1
AND (s.goods_name LIKE CONCAT('%', #{keyword}, '%') OR s.subtitle LIKE CONCAT('%', #{keyword}, '%'))
AND s.category = #{category}

SELECT FROM sku s LEFT JOIN group_buy_activity a ON a.id = ( SELECT MAX(a2.id) FROM group_buy_activity a2 WHERE a2.goods_id = s.goods_id ) LEFT JOIN group_buy_discount d ON d.discount_id = a.discount_id WHERE 1 = 1
AND (s.goods_id LIKE CONCAT('%', #{keyword}, '%') OR s.goods_name LIKE CONCAT('%', #{keyword}, '%'))
AND s.status = #{status}
ORDER BY s.update_time DESC, s.id DESC LIMIT #{offset}, #{pageSize}

SELECT COUNT(1) FROM sku s WHERE 1 = 1
AND (s.goods_id LIKE CONCAT('%', #{keyword}, '%') OR s.goods_name LIKE CONCAT('%', #{keyword}, '%'))
AND s.status = #{status}

mapper.update:
UPDATE sku
SET status = #{productStatus}, version = version + 1, update_time = NOW()
WHERE goods_id = #{goodsId} AND version = #{version}

UPDATE group_buy_activity
SET status = #{activityStatus}, update_time = NOW()
WHERE activity_id = #{activityId}

UPDATE sc_sku_activity
SET status = #{status}, update_time = NOW()
WHERE goods_id = #{goodsId} AND source = #{source} AND channel = #{channel}
